import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT','SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running row left by a killed worker is safe to retry. The attempt was counted
// when it was claimed, so it consumes one of the same three total attempts.
db.exec('BEGIN IMMEDIATE');
const nowIso = new Date().toISOString();
db.prepare(`UPDATE jobs SET status=CASE WHEN attempts >= 3 THEN 'failed' ELSE 'queued' END,
  error=CASE WHEN attempts >= 3 THEN 'transient failure' ELSE NULL END,
  completed=0, available_at=0, updated_at=? WHERE status='running'`).run(nowIso);
db.exec('COMMIT');

function beat(): void {
  db.prepare(`INSERT INTO worker_heartbeat(id,seen_at) VALUES(1,?)
    ON CONFLICT(id) DO UPDATE SET seen_at=excluded.seen_at`).run(Date.now());
}
console.log('worker started');
while (!stopping) {
  beat();
  const claimed = (() => {
    db.exec('BEGIN IMMEDIATE');
    try {
      const row = db.prepare(`SELECT id,input,steps,fail_attempts,attempts FROM jobs
        WHERE status='queued' AND available_at<=? ORDER BY created_at ASC,rowid ASC LIMIT 1`).get(Date.now()) as
        {id:string;input:string;steps:number;fail_attempts:number;attempts:number}|undefined;
      if (!row) { db.exec('COMMIT'); return undefined; }
      const stamp = new Date().toISOString();
      db.prepare(`UPDATE jobs SET status='running',attempts=attempts+1,completed=0,error=NULL,updated_at=? WHERE id=? AND status='queued'`).run(stamp,row.id);
      db.exec('COMMIT'); return {...row, attempts:row.attempts+1};
    } catch (e) { try { db.exec('ROLLBACK'); } catch {} throw e; }
  })();
  if (!claimed) { await sleep(100); continue; }
  let failed = false;
  for (let step=1; step<=claimed.steps; step++) {
    // The simulated dependency fails before the first step is recorded.
    if (step === 1 && claimed.attempts <= claimed.fail_attempts) { failed = true; break; }
    await sleep(100);
    const stamp = new Date().toISOString();
    db.prepare(`UPDATE jobs SET completed=?,updated_at=? WHERE id=? AND status='running'`).run(step,stamp,claimed.id);
    beat();
  }
  const finish = new Date().toISOString();
  if (failed) {
    if (claimed.attempts >= 3) {
      db.prepare(`UPDATE jobs SET status='failed',completed=0,error='transient failure',output=NULL,updated_at=? WHERE id=?`).run(finish,claimed.id);
    } else {
      db.prepare(`UPDATE jobs SET status='queued',completed=0,error=NULL,output=NULL,available_at=?,updated_at=? WHERE id=?`)
        .run(Date.now()+500,finish,claimed.id);
    }
  } else {
    db.prepare(`UPDATE jobs SET status='completed',completed=steps,output=?,error=NULL,updated_at=? WHERE id=?`)
      .run(claimed.input.toUpperCase(),finish,claimed.id);
  }
}
db.close();
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
