function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' }); res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: {field:string;message:string}[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
async function readBody(req: IncomingMessage): Promise<string> {
  let body = ''; for await (const chunk of req) { body += chunk.toString(); if (body.length > 100_000) throw new Error('body too large'); }
  return body;
}
const port = Number(process.env.PORT ?? 3000);
const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const idMatch = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  const known = pathname === '/' || pathname === '/health' || pathname === '/api/jobs' || !!idMatch;
  if (!known) return error(res, 404, 'not_found', 'Not found.');
  if ((pathname === '/' || pathname === '/health') && req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
  if ((pathname === '/api/jobs' && !['GET','POST'].includes(req.method ?? '')) || (idMatch && req.method !== 'GET'))
    return error(res, 405, 'method_not_allowed', 'Method not allowed.');
  if (pathname === '/' && req.method === 'GET') {
