  const input = obj.input as string; const normalizedSteps = steps as number; const normalizedFails = failAttempts as number;
  const idempotencyKey = typeof key === 'string' ? key : undefined;
  const payload = JSON.stringify({input, steps:normalizedSteps, failAttempts:normalizedFails});
  try {
    db.exec('BEGIN IMMEDIATE');
    if (idempotencyKey !== undefined) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key=?').get(idempotencyKey) as (Parameters<typeof toJob>[0] & {payload:string})|undefined;
      if (existing) {
        db.exec('COMMIT');
        if (existing.payload !== payload) return error(res,409,'idempotency_conflict','Idempotency key was already used with a different payload.');
        return send(res,200,toJob(existing));
      }
    }
    const id = randomUUID(); const now = new Date().toISOString();
    db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,completed,created_at,updated_at,idempotency_key,payload)
      VALUES(?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?, ?)`).run(id,input,normalizedSteps,normalizedFails,now,now,idempotencyKey ?? null,idempotencyKey === undefined ? null : payload);
